#include <iostream>
#include <string>

int main() {
    std::string user_input;
    std::getline(std::cin, user_input);
    int i = 1;
    while (i < static_cast<int>(user_input.length()) - 2) {
        if (user_input[i] == 'a' && user_input[i + 1] == 't') {
            user_input = user_input.substr(0, i) + '@' + user_input.substr(i + 2);
            break;
        }
        ++i;
    }
    int j = 1;
    while (j < static_cast<int>(user_input.length()) - 3) {
        if (user_input[j] == 'd' && user_input[j + 1] == 'o' && user_input[j + 2] == 't') {
            user_input = user_input.substr(0, j) + '.' + user_input.substr(j + 3);
        }
        ++j;
    }
    std::cout << user_input << std::endl;
    return 0;
}
